import ast, collections, hashlib, json, os, re, subprocess
from pathlib import Path
from urllib.parse import unquote, urlsplit
BASE = 'c2afa6b0cd089c3c9408fe7e20f623d0562c32b7'
PRIVATE = Path('/tmp/style-m3-a9-20261017')
REPORT = Path('docs/review/M3-A9-DOCS-2026-10-17.json')
ACCEPTANCE = Path('docs/review/M3-A9-2026-10-17.json')
MD = [Path(p) for p in ['docs/STYLE-M3-TASKS.md', 'docs/STYLE-M3-TESTS.md', 'docs/PROGRESS.md', 'docs/spec/STYLE-cli-design.md', 'docs/spec/STYLE-spec-rules.md', 'docs/spec/STYLE-spec-runtime.md', 'docs/spec/STYLE-spec-compiled.md', 'docs/STYLE-ADAPTERS-CURRENT.md', 'docs/review/M3-D4-REFRESH-2026-10-17.md', 'docs/STYLE-REFRESH.md']]
def need(ok,msg):
 if not ok: raise AssertionError(msg)
def git(*args): return subprocess.check_output(['git',*args])
def sha(data): return hashlib.sha256(data).hexdigest()
def fences(source):
 out=[];blocks=[];active=None;body=[]
 for line in source.splitlines():
  f=re.match(r'^\s{0,3}(`{3,}|~{3,})(.*)$',line)
  if active is None and f: active=(f[1][0],len(f[1]),f[2].strip());body=[]
  elif active and f and f[1][0]==active[0] and len(f[1])>=active[1] and not f[2].strip(): blocks.append((active[2],'\n'.join(body)+'\n'));active=None
  elif active: body.append(line)
  else: out.append(line)
 need(active is None,'unclosed fence');return '\n'.join(out),blocks

def slugs(source):
 result=set();counts=collections.Counter()
 for line in fences(source)[0].splitlines():
  m=re.match(r'^#{1,6}\s+(.+?)\s*#*$',line)
  if m:
   h=re.sub(r'<[^>]+>','',m[1]).strip().lower();h=re.sub(r'[^\w\- ]','',h).replace(' ','-')
   result.add(h+(f'-{counts[h]}' if counts[h] else ''));counts[h]+=1
 return result

def entries(source):
 rows=re.findall(r'^- \[([ x~!?])\] \*\*(M3-[A-Z0-9-]+) (.+?)\*\*(.*)$',source,re.M)
 need(len(rows)==len({r[1] for r in rows}),'duplicate id');return {i:(s,t,b) for s,i,t,b in rows}

def refs(source):
 def expand(m):
  prefix,first,middle,last=m.groups();need(middle in (None,prefix.split('-')[-1]),'range')
  width=len(first) if first.startswith('0') else 0
  return ' '.join(prefix+str(i).zfill(width) for i in range(int(first),int(last)+1))
 source=re.sub(r'(M3-(?:[A-Z]+-)*[A-Z]*)(\d+)[–—]([A-Z]+-?)?(\d+)',expand,source)
 return set(re.findall(r'\bM3-[A-Z0-9]+(?:-[A-Z0-9]+)*\b',source))


if not REPORT.exists(): REPORT.write_text('{}\n')
acceptance = json.loads(ACCEPTANCE.read_text())
need(acceptance['status'] == 'passed' and acceptance['source_base'] == BASE, 'acceptance')
code = set()
for folder, names in {
 'core/compile': 'build.go entries.go json.go provenance.go types.go refresh_test.go',
 'core/engine': 'load.go process.go trace.go types.go refresh_test.go',
 'core/plan': 'events.go plan.go report.go requirements.go system.go types.go refresh_test.go',
 'core/spec': 'native.go validate_package.go validate_rules.go refresh.go refresh_test.go',
 'core/state': 'dedup.go snapshot.go state.go refresh.go refresh_fault_test.go refresh_lock.go refresh_lock_other.go refresh_lock_unix.go refresh_test.go',
 'core/tokens': 'refresh_test.go',
 'internal/app': 'doctor.go explain_command.go install.go refresh_test.go',
 'internal/runtime': 'runtime.go refresh_test.go',
 'schema': 'index.schema.json',
 'scripts': 'check_m3_refresh.py'
}.items():
 code |= {folder + '/' + name for name in names.split()}
need(set(acceptance['source_sha256']) == code, 'source inventory')
for name in code: need(sha(Path(name).read_bytes()) == acceptance['source_sha256'][name], 'source drift '+name)
allowed = code | {str(p) for p in MD} | {str(REPORT), str(ACCEPTANCE)}
old_progress = git('show', BASE + ':docs/PROGRESS.md')
progress = Path('docs/PROGRESS.md').read_bytes()
need(progress.startswith(old_progress) and len(progress) > len(old_progress), 'append-only progress')
links = externals = shells = json_blocks = 0
for path in MD:
 source = path.read_text() if str(path) != 'docs/PROGRESS.md' else progress[len(old_progress):].decode()
 need(source.endswith('\n') and all(line == line.rstrip() for line in source.splitlines()), str(path) + ': whitespace')
 visible, blocks = fences(source)
 for lang, content in blocks:
  if lang in ('sh','bash','zsh'):
   r = subprocess.run(['zsh','-n'],input=content,text=True,capture_output=True);need(r.returncode == 0, str(path) + ': shell '+r.stderr);shells += 1
  if lang == 'json': json.loads(content);json_blocks += 1
 for match in re.finditer(r'\[[^\]\n]+\]\(([^)\n]+)\)', visible):
  target = match[1].strip().strip('<>');u = urlsplit(target)
  if u.scheme or u.netloc: externals += 1;continue
  dest = (path.parent/unquote(u.path)).resolve() if u.path else path.resolve()
  need(dest.exists(),str(path)+': missing '+target)
  if u.fragment: need(unquote(u.fragment) in slugs(dest.read_text()),str(path)+': anchor '+target)
  links += 1

task_path = Path('docs/STYLE-M3-TASKS.md');test_path = Path('docs/STYLE-M3-TESTS.md')
tasks = entries(task_path.read_text());tests = entries(test_path.read_text())
old_tasks = entries(git('show', BASE+':'+str(task_path)).decode());old_tests = entries(git('show', BASE+':'+str(test_path)).decode())
need(len(tasks) == 44 and tasks.keys() == old_tasks.keys(), 'task inventory')
need(len(tests) == 39 and tests.keys() == old_tests.keys(), 'test inventory')
for i,row in tasks.items(): need(row[0] == ('x' if i == 'M3-T40' else old_tasks[i][0]),i+': state')
for i,row in tests.items(): need(row[0] == ('x' if i == 'M3-A9' else old_tests[i][0]),i+': state')
deps = {};mapped = set()
for i,(_,_,body) in tasks.items():
 for field in ['目标','依赖：','产出：','测试：']: need(field in body,i+': '+field)
 deps[i] = refs(re.search(r'依赖：([^。；]+)',body)[1])
 need(deps[i] <= tasks.keys(),i+': dependency')
 need(deps[i] == refs(re.search(r'依赖：([^。；]+)',old_tasks[i][2])[1]),i+': dependency drift')
 targets = refs(re.search(r'测试：([^。；]+)',body)[1]);need(targets and targets <= tests.keys(),i+': test mapping');mapped |= targets
need(mapped == tests.keys(), 'test coverage')
def ancestors(i,path=()):
 need(i not in path,'dependency cycle');return deps[i] | set().union(*(ancestors(d,path+(i,)) for d in deps[i]))
for i in tasks: ancestors(i)
for i,(_,_,body) in tests.items():
 m = re.match(r'（([^）]+)）',body);need(m and refs(m[1]) and refs(m[1]) <= tasks.keys(),i+': reverse mapping')
need('M3-CARRY-01' not in ancestors('M3-FINAL'),'count carry became blocking')
for i in ['M3-T31','M3-T32']:need(tasks[i][0] == ' ' and '暂缓' in tasks[i][2],i+': deferral')
need(tasks['M3-D3'][0] == '~' and tasks['M3-D5'][0] == ' ' and tasks['M3-T41'][0] == ' ', 'scope boundary')
draft = Path('docs/review/M3-D4-REFRESH-2026-10-17.md').read_text()
rows = re.findall(r'^\| (A9-\d{2}) \| \[([ x])\] \|',draft,re.M)
need(rows == [(f'A9-{i:02d}','x') for i in range(1,13)], 'A9 inventory/states')
need([v['id'] for v in acceptance['acceptance_groups']] == [i for i,_ in rows], 'A9 evidence mapping')
need(all(v['status'] == 'passed' for v in acceptance['acceptance_groups']), 'A9 evidence')
protected = archives = previous_m3 = fixtures = agenthooks = dependencies = 0
for raw in git('ls-tree','-rz','--full-tree',BASE).split(b'\0'):
 if not raw:continue
 meta,name = raw.split(b'\t',1);mode,kind,oid = meta.decode().split();name = name.decode()
 if name in allowed:continue
 data = os.readlink(name).encode() if mode == '120000' else Path(name).read_bytes()
 need(hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest() == oid,'protected '+name)
 protected += 1
 archives += bool(re.match(r'docs/(?:STYLE-M[12]|review/M[12])',name))
 previous_m3 += name.startswith('docs/review/M3') and name.endswith('.json')
 fixtures += name.startswith('testdata/')
 agenthooks += name.startswith('agenthooks/')
 dependencies += name in ('go.mod','go.sum','go.work','go.work.sum')
need(archives == 77, 'archive count')
changed = set(git('diff','--name-only',BASE).decode().splitlines()) | set(git('ls-files','--others','--exclude-standard').decode().splitlines())
# The report is created by this audit after the inventory is checked.
need(changed | {str(REPORT)} == allowed, 'unexpected changes '+str((changed | {str(REPORT)}) ^ allowed))
go = sorted(p for p in code if p.endswith('.go'))
need(not subprocess.check_output(['gofmt','-l',*go],text=True).strip(), 'gofmt')
ast.parse(Path('scripts/check_m3_refresh.py').read_text())
for p in [ACCEPTANCE,Path('schema/index.schema.json')]:json.loads(p.read_text())
for p in allowed - {str(REPORT)}:
 data = Path(p).read_bytes();need(data.endswith(b'\n') and all(l == l.rstrip() for l in data.splitlines()),'whitespace '+p)
git('diff','--check',BASE)
verification = {'local_links_and_anchors':links,'external_reference_occurrences':externals,'markdown_fences':'balanced','shell_blocks_syntax_checked':shells,'json_blocks_checked':json_blocks,'task_entries':44,'test_entries':39,'dependencies':'unchanged and acyclic','task_test_mapping':'complete both directions','state_changes_only':['M3-T40 [ ] -> [x]','M3-A9 [ ] -> [x]'],'A9_subcases':'12 passed','deferred_and_real_states_unchanged':True,'official_count':'both 0/40; nonblocking carry unchanged','PROGRESS_append_only':True,'PROGRESS_prefix_sha256':sha(old_progress),'M1_M2_archives_unchanged':archives,'historical_M3_JSON_unchanged':previous_m3,'existing_testdata_files_unchanged':fixtures,'agenthooks_files_unchanged':agenthooks,'dependency_files_unchanged':dependencies,'other_protected_baseline_files_unchanged':protected,'gofmt_files':len(go),'python_syntax':'passed','git_diff_check':'passed; final staged check still required','new_and_tracked_whitespace':'passed','approved_paths':len(allowed)}
r = {'format':1,'task':'M3-T40','test':'M3-A9','date':'2026-10-17','status':'passed','source_base':BASE,'acceptance_report_sha256':sha(ACCEPTANCE.read_bytes()),'verification':verification,'document_sha256':{str(p):sha(p.read_bytes()) for p in MD},'changed_paths':sorted(allowed),'audit':{'source':Path(__file__).read_text(),'sha256':sha(Path(__file__).read_bytes()),'reproduction':'Extract source to a temporary Python file, run from the repository with recorded acceptance report. It verifies baseline identity, source hashes, docs and mappings; writes this report. Final staged diff --check is a separate required precommit command.'}}
REPORT.write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(verification,ensure_ascii=False,indent=2))
